UPDATE sch10_ipo
   SET sch10_item_nm                    = #{p.itemName}
     , sch10_demand_start_date          = #{p.demandStartDate}
     , sch10_demand_close_date          = #{p.demandCloseDate}
     , sch10_subscription_start_date    = #{p.subscriptionStartDate}
     , sch10_subscription_close_date    = #{p.subscriptionCloseDate}
     , sch10_div_date                   = #{p.divDate}
     , sch10_pay_date                   = #{p.payDate}
     , sch10_refund_date                = #{p.refundDate}
     , sch10_list_date                  = #{p.listDate}
     , sch10_note                       = #{p.note}
     , sch10_company_id                 = #{p.companyId}
     , sch10_market_cd                  = #{p.marketCode}
     , sch10_cancel_yn                  = #{p.cancelYn}
     , sch10_price_bracket              = #{p.priceBracket}
     , sch10_price                      = #{p.price}
     , sch10_iss_corp_cd                = #{p.issCorpCode}
 WHERE sch10_ipo_id = #{p.ipoId}
